package org.transittr;
import android.content.Context;import java.io.*;import java.net.URLEncoder;import java.util.*;import org.json.*;
/** Aykart anonymous transport data. Stop ETAs and line-fleet GPS remain distinct. */
public final class AsisCityClient {
 private static final String BASE="https://webservice.akillibiletim.com/AbysCoreApiv2/";private JSONObject index;private String token="";private long expires;private final int city;private final CityRegistry.City config;private static Context context;private static final LinkedHashMap<Integer,AsisCityClient> clients=new LinkedHashMap<Integer,AsisCityClient>();
 private AsisCityClient(int id){city=id;config=CityRegistry.get(id);}
 public static synchronized AsisCityClient forCity(int id){AsisCityClient c=clients.get(Integer.valueOf(id));if(c==null){c=new AsisCityClient(id);clients.put(Integer.valueOf(id),c);while(clients.size()>2)clients.remove(clients.keySet().iterator().next());}return c;}
 public static void init(Context value){context=value.getApplicationContext();}
 private synchronized JSONObject index()throws IOException{if(index!=null)return index;if(context==null)throw new IOException("ASİS kataloğu hazır değil");try{InputStream in=new java.util.zip.GZIPInputStream(context.getAssets().open("city-catalog-"+city+".dbz"));ByteArrayOutputStream b=new ByteArrayOutputStream();try{byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){if(b.size()+n>4194304)throw new IOException("ASİS dizini sınırı");b.write(buf,0,n);}}finally{in.close();}index=new JSONObject(new String(b.toByteArray(),"UTF-8"));return index;}catch(JSONException e){throw new IOException("ASİS dizini okunamadı");}}
 private Map<String,String> headers()throws IOException{Map<String,String> h=new HashMap<String,String>();h.put("publicAPIKey",config.key);h.put("packagename","com.asis.akillibilet");h.put("deviceid","transit-tr-anonymous");h.put("version","43256");h.put("versionname","4.0.43.256");h.put("devicemodel","Android");h.put("buildvariant","release");h.put("operatingsystem","Android");h.put("osapiversion","23");h.put("User-Agent","AkilliBilet/4.0.43.256");h.put("language","tr");h.put("X-AuthKey",AsisAuth.generate());return h;}
 private synchronized String token()throws IOException{if(token.length()>0&&System.currentTimeMillis()<expires)return token;try{JSONObject d=new JSONObject(ApiHttp.text(BASE+"token",("grant_type=client_credentials&Language=tr&CityCode="+config.asisCode).getBytes("US-ASCII"),"application/x-www-form-urlencoded",headers(),16384));token=d.getString("access_token");expires=System.currentTimeMillis()+20*60000L;return token;}catch(JSONException e){throw new IOException("ASİS anonim erişimi alınamadı");}}
 JSONObject request(String path,JSONObject body)throws IOException{for(int attempt=0;attempt<2;attempt++){String t=token();Map<String,String> h=headers();h.put("Authorization","Bearer "+t);try{JSONObject value=new JSONObject(ApiHttp.text(BASE+path,body==null?null:body.toString().getBytes("UTF-8"),"application/json; charset=utf-8",h,4194304));int status=value.optInt("StatusCode",200);if(status!=200&&status!=204)throw new IOException(config.name+" ulaşım servisi hata verdi ("+status+")");return value;}catch(JSONException e){throw new IOException("ASİS yanıtı okunamadı");}catch(IOException e){if(attempt==0&&e.getMessage()!=null&&e.getMessage().indexOf("401")>=0){synchronized(AsisCityClient.class){token="";}continue;}throw e;}}throw new IOException("ASİS erişimi yenilenemedi");}
 private static JSONArray result(JSONObject d,String key)throws JSONException{JSONObject r=d.optJSONObject("Result");JSONArray a=r==null?null:r.optJSONArray(key);return a==null?new JSONArray():a;}
 private JSONObject findRoute(String code)throws IOException{try{JSONArray rows=index().getJSONArray("routes");String q=CatalogStore.normalize(code);for(int k=0;k<rows.length();k++){JSONObject r=rows.getJSONObject(k);if(q.equals(CatalogStore.normalize(r.optString("displayRouteCode")))||q.equals(CatalogStore.normalize(r.optString("originalCode")))||q.equals(CatalogStore.normalize(r.optString("name"))))return r;}return null;}catch(JSONException e){throw new IOException("ASİS hat kodu okunamadı");}}
 public JSONArray searchStops(String query)throws IOException{try{JSONArray all=index().getJSONArray("stops"),out=new JSONArray();String q=CatalogStore.normalize(query.trim());for(int k=0;k<all.length();k++){JSONObject r=all.getJSONObject(k);if(CatalogStore.normalize(r.optString("stopId")+" "+r.optString("name")).contains(q))out.put(r);}return out;}catch(JSONException e){throw new IOException("ASİS durakları okunamadı");}}
 public JourneyData.Station stop(String code)throws IOException{try{JSONArray a=searchStops(code);for(int k=0;k<a.length();k++){JSONObject r=a.getJSONObject(k);if(code.equals(r.optString("stopId"))){JourneyData.Station s=new JourneyData.Station(r.optString("name"),SourceTools.number(r,"lat"),SourceTools.number(r,"lng"));s.code=code;return s;}}return null;}catch(JSONException e){throw new IOException("ASİS durağı okunamadı");}}
 public JourneyData.Snapshot query(String stop,String filter)throws IOException{return query(stop,filter,true);}
 public JourneyData.Snapshot query(String stop,String filter,boolean gps)throws IOException{try{JSONObject body=new JSONObject();body.put("stopId",Integer.parseInt(stop));JSONObject d;JSONArray eta;try{d=request("Avl/Get/StationApproachingVehicles?StationId="+Integer.parseInt(stop),null);JSONObject result=d.optJSONObject("Result");eta=result==null?null:result.optJSONArray("Route");}catch(IOException ignored){eta=null;}if(eta==null||eta.length()==0){d=request("StationRemainingTime",body);eta=d.optJSONArray("Result");}JourneyData.Snapshot s=new JourneyData.Snapshot();s.source=config.name+" / ASİS";s.separateMapRows=true;s.suggestedRefreshMillis=30000;JSONObject selected=filter.length()>0?findRoute(filter):null;if(filter.length()>0&&selected==null)throw new IOException("ASİS hat kodu bulunamadı");String original=selected==null?"":selected.optString("originalCode");HashSet<String> fleet=new HashSet<String>();if(original.length()>0)fleet.add(original);
  if(eta!=null){if(eta.length()>200)throw new IOException("ASİS varış sınırı");for(int k=0;k<eta.length();k++){JSONObject r=eta.getJSONObject(k),route=findRoute(r.optString("BusLineCode"));String code=route==null?r.optString("BusLineCode"):route.optString("displayRouteCode");if(!SourceTools.matches(code,filter))continue;JourneyData.Vehicle v=new JourneyData.Vehicle();v.id="asis:"+city+":"+k;v.line=code;v.name=r.optString("BusLineShortName","");int minutes=r.isNull("RemainingTimeCurr")?-1:r.optInt("RemainingTimeCurr",-1);v.etaSeconds=minutes>=0&&minutes<1440?minutes*60L:-1;v.eta=SourceTools.minutes(v.etaSeconds);v.arrivalStop=stop;v.etaIsStopArrival=v.etaSeconds>=0;s.rows.add(v);if(fleet.size()<4)fleet.add(r.optString("BusLineCode"));}}
  if(gps)for(String code:fleet){if(code.length()==0)continue;JSONObject b=new JSONObject();b.put("RouteCode",code);JSONArray vehicles=request("RealTimeData",b).optJSONArray("Result");if(vehicles!=null)appendGps(s,vehicles,findRoute(code));}
  SourceTools.sort(s);if(s.rows.isEmpty())s.emptyMessage=filter.length()==0?"Bu durakta varış kaydı yok. Hat GPS’i için bir hat kodu gir.":"Bu durakta varış kaydı yok; varsa seçili hattın GPS araçları haritada.";if(s.positionCount()>0)s.message="Hat GPS filosu gösteriliyor; bu araçlar seçili durağa yaklaşan araç listesi değildir.";return s;
 }catch(JSONException e){throw new IOException("ASİS canlı verisi okunamadı");}catch(NumberFormatException e){throw new IOException("Geçerli Aydın durak numarası gir");}}
 public static void appendGps(JourneyData.Snapshot s,JSONArray rows,JSONObject route)throws JSONException,IOException{if(rows.length()>200)throw new IOException("ASİS GPS sınırı");for(int k=0;k<rows.length();k++){JSONObject r=rows.getJSONObject(k);JourneyData.Vehicle v=new JourneyData.Vehicle();v.id="aydin:"+r.optString("plaka");v.line=route==null?r.optString("Hatkodu"):route.optString("displayRouteCode");v.name=route==null?r.optString("Hatkodu"):route.optString("name");v.lat=SourceTools.number(r,"enlem");v.lon=SourceTools.number(r,"boylam");v.sourceTime=r.optString("editDate","");v.observedAt=SourceTools.time(v.sourceTime);v.eta="GPS";if(v.hasPosition())s.mapRows.add(v);}}
 public JourneyData.Route route(String code,String name)throws IOException{try{JSONObject record=findRoute(code);if(record==null)throw new IOException("ASİS hattı bulunamadı");JSONArray rows=result(request("Avl/Get/RouteByRouteId?RouteIds="+URLEncoder.encode(record.getString("routeCode"),"UTF-8"),null),"Route");if(rows.length()==0)throw new IOException("ASİS güzergâhı bulunamadı");JSONArray variants=rows.getJSONObject(0).getJSONArray("RouteVariants");if(variants.length()==0)throw new IOException("ASİS yönü bulunamadı");JSONObject v=variants.getJSONObject(0);JourneyData.Route out=new JourneyData.Route();out.code=code;out.name=name;out.source="ASİS / ASİS güzergâh servisi";out.notice=v.optString("Title","");out.schematic=false;JSONObject geom=new JSONObject(v.getString("Geom")).getJSONObject("geometry");JSONArray parts=geom.getJSONArray("coordinates");if(geom.getString("type").equals("LineString")){JSONArray wrap=new JSONArray();wrap.put(parts);parts=wrap;}int points=0;for(int k=0;k<parts.length();k++){JSONArray a=parts.getJSONArray(k);ArrayList<JourneyData.Station> part=new ArrayList<JourneyData.Station>();for(int j=0;j<a.length();j++){if(++points>20000)throw new IOException("ASİS çizgi sınırı");JSONArray p=a.getJSONArray(j);double lon=p.getDouble(0),lat=p.getDouble(1);if(lat>=35&&lat<=43&&lon>=25&&lon<=45)part.add(new JourneyData.Station("",lat,lon));}if(part.size()>1)out.parts.add(part);}JSONArray groups=result(request("Avl/Get/RouteVariantStations?RouteVariantId="+v.getInt("Id"),null),"routeVariantStops");if(groups.length()>0){JSONArray stops=groups.getJSONObject(0).getJSONArray("station");for(int k=0;k<stops.length()&&k<1000;k++){JSONObject p=stops.getJSONObject(k);JourneyData.Station st=new JourneyData.Station(p.optString("Title",p.optString("StopTitle","")),SourceTools.number(p,"Latitude"),SourceTools.number(p,"Longitude"));st.code=p.optString("Id");out.stops.add(st);if(st.lat>=35&&st.lat<=43&&st.lon>=25&&st.lon<=45)out.mappedStops++;}}return out;}catch(JSONException e){throw new IOException("ASİS rota verisi okunamadı");}}
}
